  "conditioning": {
    "format": "for_time",
    "duration_min": 13,
    "stimulus": "technical",
    "movements": [
      {
        "key": "push_up",
        "amount": "12reps",
        "name_ko": "푸시업"
      },
      {
        "key": "sit_up",
        "amount": "12reps",
        "name_ko": "싯업"
      },
      {
        "key": "row",
        "amount": "250m",
        "name_ko": "로잉"
      }
    ],
    "equipment": [
      "bodyweight",
      "rower"
    ],
    "volume": "low",
    "intensity": "moderate"
  }
}

